import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-DrdKnICy.js";var i=JSON.parse(`{"path":"/software-exam/integrated/project-schedule-management/comprehensive-exercises/","title":"1 综合练习 | 软考","lang":"zh-CN","frontmatter":{"title":"1 综合练习","createTime":"2026-11-21T19:30:00.000Z","permalink":"/software-exam/integrated/project-schedule-management/comprehensive-exercises/","outline":false,"aside":false},"readingTime":{"minutes":63.84,"words":19153},"git":{"createdTime":1795264775000},"filePathRelative":"software-exam/integrated/project-schedule-management/1.comprehensive-exercises.md","headers":[],"bulletin":false}`),a={name:`1.comprehensive-exercises.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="exam-note"><p><a id="q1" class="quiz-anchor"></a></p><p><strong>1.</strong> 规划进度管理是为规划、（ ）和控制项目进度而制定政策、程序和文档的过程。</p><ul><li>A．编制、管理、执行</li><li>B．编制、管理、分解</li><li>C．管理、执行、分解</li><li>D．编制、执行、分解</li></ul><details class="quiz" data-q="1" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：规划进度管理 = 为规划、编制、管理、执行和控制项目进度而制定政策、程序和文档（P384）　<span class="quiz-src">自编</span></p></details><p><a id="q2" class="quiz-anchor"></a></p><p><strong>2.</strong> 关于进度管理计划的理解，不正确的是（ ）。</p><ul><li>A．进度管理计划是项目管理计划的组成部分</li><li>B．进度管理计划既可以非常详细，也可以高度概括，但必须是正式的</li><li>C．进度管理计划为编制、监督和控制项目进度建立准则和明确活动</li><li>D．进度管理计划会规定用于制定项目进度模型的进度规划方法论和工具</li></ul><details class="quiz" data-q="2" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：进度管理计划可以是正式或非正式的，非常详细或高度概括的（P385）　<span class="quiz-src">自编</span></p></details><p><a id="q3" class="quiz-anchor"></a></p><p><strong>3.</strong> 关于项目进度管理计划的描述，正确的是（ ）。</p><ul><li>A．项目进度管理计划一旦确定，不能被修改</li><li>B．在制定项目进度管理计划时，应该考虑项目章程</li><li>C．项目进度管理计划一定要形成正式的文件</li><li>D．项目进度管理计划是详细的，不能是高度概括的</li></ul><details class="quiz" data-q="3" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目章程是制定进度管理计划的输入；计划可通过变更修订，形式可正式或非正式（P385）　<span class="quiz-src">自编</span></p></details><p><a id="q4" class="quiz-anchor"></a></p><p><strong>4.</strong> （ ）属于规划项目进度管理过程的输出。</p><ul><li>A．项目管理计划</li><li>B．项目章程</li><li>C．事业环境因素</li><li>D．控制临界值</li></ul><details class="quiz" data-q="4" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：控制临界值属进度管理计划内容；A、B、C 均为规划进度管理的输入（P385）　<span class="quiz-src">自编</span></p></details><p><a id="q5" class="quiz-anchor"></a></p><p><strong>5.</strong> 规划进度管理的输出不包括（ ）。</p><ul><li>A．开发方法</li><li>B．进度管理计划</li><li>C．控制临界值</li><li>D．绩效测量规则</li></ul><details class="quiz" data-q="5" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：规划进度管理输出为进度管理计划（含临界值、绩效测量规则等）；开发方法属项目管理计划其他内容（P385）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q6" class="quiz-anchor"></a></p><p><strong>6.</strong> 进度管理计划的主要内容是（ ）。</p><ul><li>A．项目进度模型</li><li>B．进度基准</li><li>C．项目进度计划</li><li>D．项目日历</li></ul><details class="quiz" data-q="6" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：进度管理计划内容包括项目进度模型、发布和迭代长度、准确度、计量单位、WBS、模型维护、控制临界值、绩效测量规则、报告格式（P385）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q7" class="quiz-anchor"></a></p><p><strong>7.</strong> 关于进度管理计划的概述，不正确的是（ ）。</p><ul><li>A．进度管理计划既可以是正式的也可以是非正式的，既可以是非常详细的也可以是高度概括的</li><li>B．项目管理计划中规定的偏差临界值，可以用于监督进度绩效，通常用偏离基准计划中的参数的某个百分数来表示</li><li>C．在采用适应型生命周期时，应指定进度管理计划发布，规划和迭代的固定时间段</li><li>D．进度管理计划描述如何定义、制定、监督、控制和确认项目范围，是项目管理计划的组成部分</li></ul><details class="quiz" data-q="7" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：D 描述的是范围管理计划；进度管理计划是为编制、监督和控制项目进度建立准则和明确活动（P385）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q8" class="quiz-anchor"></a></p><p><strong>8.</strong> 进度管理计划中要求进度偏差超过基准计划的 5% 时需启动纠偏，该规定属于进度管理计划中的（ ）。</p><ul><li>A．控制临界值</li><li>B．准确度</li><li>C．绩效测量规则</li><li>D．计量单位</li></ul><details class="quiz" data-q="8" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：控制临界值 = 需要采取某种措施前允许出现的最大差异，常用偏离基准计划参数的某个百分数表示（P385）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q9" class="quiz-anchor"></a></p><p><strong>9.</strong> 定义活动的主要作用是将工作包分解为进度活动，作为对项目工作进行进度估算、（ ）的基础。</p><ul><li>A．规划、执行、监督和控制</li><li>B．规划、定义、监督和控制</li><li>C．规划、执行、定义和控制</li><li>D．规划、执行、监督和定义</li></ul><details class="quiz" data-q="9" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：定义活动将工作包分解为进度活动，作为进度估算、规划、执行、监督和控制的基础（P385）　<span class="quiz-src">自编</span></p></details><p><a id="q10" class="quiz-anchor"></a></p><p><strong>10.</strong> &quot;定义活动&quot;过程的输出不包括（ ）。</p><ul><li>A．活动清单</li><li>B．范围基准</li><li>C．里程碑清单</li><li>D．活动属性</li></ul><details class="quiz" data-q="10" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：定义活动的输出为活动清单、活动属性、里程碑清单、变更请求、项目管理计划更新；范围基准是输入（P386-387）　<span class="quiz-src">自编</span></p></details><p><a id="q11" class="quiz-anchor"></a></p><p><strong>11.</strong> 在早期的战略规划阶段，信息尚不够明确，工作包只能分解到已知的详细水平，而后，随着了解到更多的信息，近期即将实施的工作包就可以分解到具体的活动，该方法是（ ）。</p><ul><li>A．专家判断</li><li>B．分解</li><li>C．滚动式规划</li><li>D．标杆管理法</li></ul><details class="quiz" data-q="11" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：滚动式规划是迭代式规划技术，近期详细规划、远期在较高层级粗略规划（P386）　<span class="quiz-src">自编</span></p></details><p><a id="q12" class="quiz-anchor"></a></p><p><strong>12.</strong> 关于活动属性的理解，不正确的是（ ）。</p><ul><li>A．活动属性是指每项活动所具有的多重属性，用来扩充对活动的描述</li><li>B．活动属性不会随时间而演进</li><li>C．活动属性可用于识别开展工作的地点、编制开展活动的项目日历，以及相关的活动类型</li><li>D．在项目初始阶段，活动属性包括唯一活动标识、WBS 标识和活动名称</li></ul><details class="quiz" data-q="12" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：活动属性随着项目进展情况演进并更新（P386）　<span class="quiz-src">自编</span></p></details><p><a id="q13" class="quiz-anchor"></a></p><p><strong>13.</strong> 关于进度管理的描述，不正确的是（ ）。</p><ul><li>A．里程碑的持续时间可以为零，也可以不为零</li><li>B．活动需要消耗资源和花费成本，里程碑不需要资源和成本</li><li>C．活动属性可能随着项目的推进而变化</li><li>D．一个项目中可能有几个达到里程碑程度的关键事件</li></ul><details class="quiz" data-q="13" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：里程碑的持续时间均为零，因为它代表的只是一个重要时间点或事件（P387）　<span class="quiz-src">自编</span></p></details><p><a id="q14" class="quiz-anchor"></a></p><p><strong>14.</strong> 关于定义活动过程的输出，描述不正确的是（ ）。</p><ul><li>A．活动属性随着项目进展情况演进并更新</li><li>B．里程碑的持续时间可以是某个事件的持续时间</li><li>C．活动属性用来扩充对活动的描述</li><li>D．里程碑清单中的里程碑不一定是强制性的</li></ul><details class="quiz" data-q="14" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：里程碑持续时间为零；里程碑清单中需标明是强制性还是选择性（P387）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q15" class="quiz-anchor"></a></p><p><strong>15.</strong> 关于定义活动过程的描述，不正确的是（ ）。</p><ul><li>A．定义活动主要由项目经理主导，也需要其他项目团队成员参与</li><li>B．定义活动完成后，应形成一份详细的活动清单</li><li>C．定义活动输出的里程碑清单是合同要求的强制性的重要时间节点和事件</li><li>D．定义活动过程中必须考虑项目的时间限制和预算约束</li></ul><details class="quiz" data-q="15" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：里程碑清单可以是合同要求的，也可以是选择性的（P387）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q16" class="quiz-anchor"></a></p><p><strong>16.</strong> 某项目经理在定义活动过程中，将工作包分解为具体的活动时，团队提出了以下四种分解方法，其中不符合定义活动最佳实践的是（ ）。</p><ul><li>A．由于某工作包涉及跨部门协作，将其整体作为一项活动，并标注由&quot;多部门共同负责&quot;作为活动属性</li><li>B．针对近期需完成的工作包，使用滚动式规划分解到详细的个人任务；对远期工作包仅分解到里程碑</li><li>C．在分解过程中，将&quot;客户验收会议&quot;作为一个独立活动，明确其所需的资源和前置条件</li><li>D．将每个工作包分解为多个活动，确保每个活动的持续时间不超过两周，以便于进度监控</li></ul><details class="quiz" data-q="16" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：责任独立原则——一项活动只能由且仅有一人负责（P383）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q17" class="quiz-anchor"></a></p><p><strong>17.</strong> 在迭代型和增量型项目中，为了有效应对需求的不确定性，并通过渐进明细来降低风险、控制成本，通常采用以下哪种规划技术（ ）。</p><ul><li>A．关键路径法</li><li>B．滚动式规划</li><li>C．计划评审技术</li><li>D．关键链法</li></ul><details class="quiz" data-q="17" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：滚动式规划是渐进明细的规划方式，适用于工作包、规划包（P386）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q18" class="quiz-anchor"></a></p><p><strong>18.</strong> 定义活动的输出不包括（ ）。</p><ul><li>A．活动清单</li><li>B．活动属性</li><li>C．进度网络图</li><li>D．里程碑清单</li></ul><details class="quiz" data-q="18" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：定义活动主要输出为活动清单、活动属性和里程碑清单；进度网络图是排列活动顺序的输出（P386）　<span class="quiz-src">2025 年中项第 4 批</span></p></details><p><a id="q19" class="quiz-anchor"></a></p><p><strong>19.</strong> 定义活动使用的工具与技术有（ ）。</p><ul><li>A．分解和滚动式规划</li><li>B．提前量和滞后量</li><li>C．紧前关系绘图法和箭线图法</li><li>D．自下而上估算</li></ul><details class="quiz" data-q="19" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：定义活动的工具与技术主要包括分解和滚动式规划等（P386）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><a id="q20" class="quiz-anchor"></a><p><strong>20.</strong> 以下项目活动中，存在 S-S 关系的活动组合是（ ）。</p><p>①功能验收；②单元测试；③功能开发；④需求确认；⑤系统集成</p><ul><li>A．④-③</li><li>B．③-②</li><li>C．③-⑤</li><li>D．①-⑤</li></ul><details class="quiz" data-q="20" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：S-S 为开始-开始关系，单元测试可在功能开发开始后即开展（P387-388）　<span class="quiz-src">自编</span></p></details><p><a id="q21" class="quiz-anchor"></a></p><p><strong>21.</strong> 前导图法可以描述四种关键活动类型的依赖关系，对于接班同事 A 到岗，交班同事 B 才可以下班的接班过程，可以用（ ）描述。</p><ul><li>A．S-F</li><li>B．F-F</li><li>C．S-S</li><li>D．F-S</li></ul><details class="quiz" data-q="21" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：S-F 开始-结束，即 A 开始后 B 才能结束（P389）　<span class="quiz-src">自编</span></p></details><p><a id="q22" class="quiz-anchor"></a></p><p><strong>22.</strong> 只有在验证请求者身份合法后，服务器才开始向客户端传输数据，这是（ ）关系。</p><ul><li>A．FS</li><li>B．FF</li><li>C．SS</li><li>D．SF</li></ul><details class="quiz" data-q="22" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：前项结束后项才开始，属完成-开始（FS）关系（P389）　<span class="quiz-src">自编</span></p></details><p><a id="q23" class="quiz-anchor"></a></p><p><strong>23.</strong> 某项目进度网络图中，活动 A 和 B 之间的依赖关系为 SS-8 天，则表明（ ）。</p><ul><li>A．活动 A 开始 8 天后活动 B 开始</li><li>B．活动 A 开始 8 天前活动 B 开始</li><li>C．活动 A 结束 8 天后活动 B 开始</li><li>D．活动 A 结束 8 天前活动 B 开始</li></ul><details class="quiz" data-q="23" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：SS 中加入提前量与滞后量；+8 表示滞后量，-8 表示提前量（P390）　<span class="quiz-src">自编</span></p></details><p><a id="q24" class="quiz-anchor"></a></p><p><strong>24.</strong> 某个程序的两个模块，模块 A 实现设备的运行功能，模块 B 实现设备运行过程中实时监控设备状态数据的功能。则项目计划网络图中，模块 A 和模块 B 的依赖关系可表示为（ ）型。</p><ul><li>A．F-S</li><li>B．F-F</li><li>C．S-S</li><li>D．S-F</li></ul><details class="quiz" data-q="24" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：设备运行过程中同时进行状态监控，两者是 S-S 关系（P389）　<span class="quiz-src">自编</span></p></details><p><a id="q25" class="quiz-anchor"></a></p><p><strong>25.</strong> 项目进度管理经常采用箭线图法，以下对箭线图的描述不正确的是（ ）。</p><ul><li>A．流入同一节点的活动，有相同的后继活动</li><li>B．虚活动不消耗时间，但消耗资源</li><li>C．箭线图中可以有两张关键路径</li><li>D．两个相关节点之间只能有一条箭线</li></ul><details class="quiz" data-q="25" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：虚活动既不消耗时间，也不消耗资源，只为弥补箭线图表达依赖关系的不足（P390）　<span class="quiz-src">自编</span></p></details><p><a id="q26" class="quiz-anchor"></a></p><p><strong>26.</strong> 以下不具有&quot;完成-开始&quot;关系的两个活动是（ ）。</p><ul><li>A．系统设计，设计评审</li><li>B．系统分析，需求评审</li><li>C．需求评审，周例会</li><li>D．确定项目范围，制定 WBS</li></ul><details class="quiz" data-q="26" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：周例会是周期性的管理活动，与需求评审没有固定的完成-开始关系（P389）　<span class="quiz-src">自编</span></p></details><p><a id="q27" class="quiz-anchor"></a></p><p><strong>27.</strong> 在某个信息系统项目中，存在新老系统切换问题，在设置项目计划网络图时，新系统上线和老系统下线之间应设置成（ ）的关系。</p><ul><li>A．结束-开始（FS 型）</li><li>B．结束-结束（FF 型）</li><li>C．开始-结束（SF 型）</li><li>D．开始-开始（SS 型）</li></ul><details class="quiz" data-q="27" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：新系统上线后老系统才能下线，属开始-结束关系（P389）　<span class="quiz-src">自编</span></p></details><p><a id="q28" class="quiz-anchor"></a></p><p><strong>28.</strong> 只有在验证请求者身份合法后，服务器才开始向客户端传输数据，这是（ ）—（ ）关系。</p><ul><li>A．FS</li><li>B．FF</li><li>C．SS</li><li>D．SF</li></ul><details class="quiz" data-q="28" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：验证结束后才开始传输，前面结束后后面才开始，属 FS 型（P389）　<span class="quiz-src">自编</span></p></details><p><a id="q29" class="quiz-anchor"></a></p><p><strong>29.</strong> 活动 B 可在活动 A 完成前 5 天开始，则关系表示为（ ）。</p><ul><li>A．SS+5</li><li>B．SS-5</li><li>C．FS+5</li><li>D．FS-5</li></ul><details class="quiz" data-q="29" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：B 须在 A 完成后开始属 FS 型；提前 5 天开始表示提前量为 -5（P390）　<span class="quiz-src">自编</span></p></details><p><a id="q30" class="quiz-anchor"></a></p><p><strong>30.</strong> 排列活动顺序时需要参考的依据不包括（ ）。</p><ul><li>A．假设日志</li><li>B．范围基准</li><li>C．进度管理计划</li><li>D．项目进度网络图</li></ul><details class="quiz" data-q="30" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目进度网络图是排列活动顺序的输出，不是依据（P387-388）　<span class="quiz-src">自编</span></p></details><p><a id="q31" class="quiz-anchor"></a></p><p><strong>31.</strong> 关于排列活动的说法中不正确的是（ ）。</p><ul><li>A．带有多个紧前活动的活动代表路径汇聚，而带有多个紧后活动的活动则代表路径分支</li><li>B．项目进度网络图中的每项活动都至少有一项紧前活动和一项紧后活动</li><li>C．排列活动顺序过程旨在将项目活动列表转化为图表，作为发布进度基准的第一步</li><li>D．排列活动顺序主要作用是定义工作之间的逻辑顺序，以便在既定的所有项目制约因素下获得最高的效率</li></ul><details class="quiz" data-q="31" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：除首尾两项外，每项活动都至少有一项紧前活动和一项紧后活动（P387）　<span class="quiz-src">自编</span></p></details><p><a id="q32" class="quiz-anchor"></a></p><p><strong>32.</strong> 关于活动排序的工具和技术，描述不正确的是（ ）。</p><ul><li>A．在前导图中，每项活动有唯一的活动号，并注明了活动的持续时间</li><li>B．箭线图中，虚活动不消耗时间，也不消耗资源</li><li>C．箭线图中，流入同一节点的活动，均有共同的紧前活动</li><li>D．前导图使用方框或者长方形代表活动，用箭头连接表示节点之间的逻辑关系</li></ul><details class="quiz" data-q="32" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：流入（流出）同一节点的活动，均有共同的紧后活动（或紧前活动）（P390）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q33" class="quiz-anchor"></a></p><p><strong>33.</strong> 在 IT 基础设施升级项目中，数据迁移活动可以在网络升级活动开始后 7 天开始数据迁移，数据迁移活动和网络升级活动之间的关系可表示为（ ）。</p><ul><li>A．SS-7</li><li>B．FS+7</li><li>C．SS+7</li><li>D．FS-7</li></ul><details class="quiz" data-q="33" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：网络升级开始 7 天后数据迁移可开始即 SS+7；反问两者关系需反推，故为 SS-7（P390）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q34" class="quiz-anchor"></a></p><p><strong>34.</strong> 关于项目进度网络图的描述，不正确的是（ ）。</p><ul><li>A．带有多个紧前活动的活动代表路径汇聚，而带有多个紧后活动的活动则代表路径分支</li><li>B．项目进度网络图用于表示项目进度活动之间的依赖关系</li><li>C．带汇聚和分支的活动存在较大风险</li><li>D．项目进度网络图不应该只包含概括性活动，应包括项目的全部细节</li></ul><details class="quiz" data-q="34" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目进度网络图可包括项目的全部细节，也可只列出一项或多项概括性活动（P391）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q35" class="quiz-anchor"></a></p><p><strong>35.</strong> 关于活动排序的描述，不正确的是（ ）。</p><ul><li>A．在单代号网络中，每项活动有唯一的活动号，每项活动都标明了活动的持续时间</li><li>B．双代号网络图中流入同一节点的活动，均有共同的紧后活动</li><li>C．双代号网络图中，任两项活动的紧前事件和紧后事件代号至少有一个不相同</li><li>D．滞后量是紧后活动相对于紧前活动需要推迟的时间量，一般用负值表示</li></ul><details class="quiz" data-q="35" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：滞后量一般用正值表示，提前量用负值表示（P390）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q36" class="quiz-anchor"></a></p><p><strong>36.</strong> （ ）不属于排列活动顺序过程的工具与技术。</p><ul><li>A．关键路径法</li><li>B．提前量和滞后量</li><li>C．紧前关系绘图法</li><li>D．箭线图法</li></ul><details class="quiz" data-q="36" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：关键路径法是制订进度计划的工具，不属于排列活动顺序（P388-391）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q37" class="quiz-anchor"></a></p><p><strong>37.</strong> 项目进度管理的各个子过程中，（ ）过程的目的是识别和记录项目活动之间的关系，（ ）过程会形成里程碑清单。</p><ul><li>A．定义活动、估算活动持续时间</li><li>B．排列活动顺序、定义活动</li><li>C．定义活动、定义活动</li><li>D．排列活动顺序、排列活动顺序</li></ul><details class="quiz" data-q="37" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：定义活动识别和记录完成可交付成果所需的具体行动；排列活动顺序识别和记录活动之间的关系；里程碑清单由定义活动形成（P385-387）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q38" class="quiz-anchor"></a></p><p><strong>38.</strong> 某公司的大模型训练项目，活动 A（数据预处理）需清晰和扩充语料，活动 B（分布式训练）需启动 GPU 集群，为缩短周期，项目经理决定在活动 A 开始 2 天后利用部分数据开展活动 B，则活动 A 与 B 的关系可表示为（ ）。</p><ul><li>A．FF-2</li><li>B．FS+2</li><li>C．SF-2</li><li>D．SS+2</li></ul><details class="quiz" data-q="38" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：A 开始 2 天后开展 B，是开始-开始加 2 天滞后量，即 SS+2（P390）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q39" class="quiz-anchor"></a></p><p><strong>39.</strong> 软件开发项目中，项目经理使用（ ）清晰展示活动之间的逻辑关系，以便团队明确工作顺序。</p><ul><li>A．迭代燃尽图</li><li>B．蒙特卡洛分析</li><li>C．资源日历</li><li>D．进度网络图</li></ul><details class="quiz" data-q="39" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目进度网络图是表示项目进度活动之间逻辑关系（依赖关系）的图形（P391）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q40" class="quiz-anchor"></a></p><p><strong>40.</strong> 活动依赖关系（ ）。</p><p>①开始 3 天后开始　②完成后开始　③在完成前 2 天开始</p><ul><li>A．FS+3，FS，FS+2</li><li>B．FS+3，FS，FS-2</li><li>C．SS+3，FS，FS-2</li><li>D．SS+3，FS，FS+2</li></ul><details class="quiz" data-q="40" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：滞后量用正值、提前量用负值；③为 FS 带 2 天提前量即 FS-2（P390）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q41" class="quiz-anchor"></a></p><p><strong>41.</strong> 以下关于估算活动持续时间如何开展的描述，正确的是（ ）。</p><ul><li>A．仅开展一次</li><li>B．仅在项目的预定义点开展</li><li>C．仅开展一次或仅在项目的预定义点开展</li><li>D．需要在整个项目期间开展</li></ul><details class="quiz" data-q="41" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：估算活动持续时间在整个项目期间开展，作用是确定完成每个活动所需花费的时间量（P391）　<span class="quiz-src">自编</span></p></details><p><a id="q42" class="quiz-anchor"></a></p><p><strong>42.</strong> 估算活动持续时间的输出不包括（ ）。</p><ul><li>A．项目管理计划</li><li>B．关于各种已知制约因素的文件</li><li>C．持续时间估算</li><li>D．估算依据</li></ul><details class="quiz" data-q="42" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目管理计划是输入；输出为持续时间估算与估算依据（含已知制约因素说明）（P394-395）　<span class="quiz-src">自编</span></p></details><p><a id="q43" class="quiz-anchor"></a></p><p><strong>43.</strong> （ ）不是活动历时估算依据。</p><ul><li>A．范围基准</li><li>B．活动资源需求</li><li>C．风险登记册</li><li>D．项目进度计划</li></ul><details class="quiz" data-q="43" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目进度计划是历时估算之后制订进度计划过程的交付物，不是历时估算依据（P393）　<span class="quiz-src">自编</span></p></details><p><a id="q44" class="quiz-anchor"></a></p><p><strong>44.</strong> 关于以下说法，（ ）是不正确的。</p><ul><li>A．收益递减规律：在保持其他因素不变的情况下，增加一个用于确定单位产出所需投入的因素（如资源）最终会达到一个临界点，在该点之后的产出或输出会随着增加这个因素而递减</li><li>B．增加资源数量，比如两倍投入资源完成工作的时间可以缩短一半</li><li>C．通过采购最新技术，制造工厂可以提高产量，而这可能会影响持续时间和资源需求</li><li>D．拖延症认为人们只有在最后一刻，即快到期限时才会全力以赴；帕金森定律认为只要还有时间，工作就会不断扩展，直到用完所有的时间</li></ul><details class="quiz" data-q="44" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：增加资源不一定按比例缩短工期，可能因额外风险、知识传递、学习曲线、额外合作等因素反而增加持续时间（P392）　<span class="quiz-src">自编</span></p></details><p><a id="q45" class="quiz-anchor"></a></p><p><strong>45.</strong> 在进行项目活动历时估算时，（ ）属于参数估算。</p><ul><li>A．从以前类似计划活动的实际持续时间为依据来估算</li><li>B．用需要完成工作的数量乘以完成单位工作所需时间为估算活动时间的依据</li><li>C．利用有可能的历时估算，最乐观的历时估算和最悲观的历时估算来计算</li><li>D．利用以历时信息为依据的专家判断估算</li></ul><details class="quiz" data-q="45" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：参数估算是利用历史数据和变量之间的统计关系计算活动资源成本（P394）　<span class="quiz-src">自编</span></p></details><p><a id="q46" class="quiz-anchor"></a></p><p><strong>46.</strong> 相对于其他估算技术，（ ）通常成本较低、耗时较少，但准确性也较低。</p><ul><li>A．类比估算</li><li>B．参数估算</li><li>C．三点估算</li><li>D．自下而上估算</li></ul><details class="quiz" data-q="46" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：类比估算成本低、耗时少但准确性较低，可针对整个项目或部分进行，也可与其他方法联用（P394）　<span class="quiz-src">自编</span></p></details><p><a id="q47" class="quiz-anchor"></a></p><p><strong>47.</strong> 在进行项目活动历时估算时，如果很难获得项目工作的详细信息，可采用（ ）作为项目活动历时估算的工具。</p><ul><li>A．参数估算</li><li>B．类比估算</li><li>C．预留时间估算</li><li>D．三点估算</li></ul><details class="quiz" data-q="47" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：项目详细信息不足时，常使用类比估算来估算项目持续时间（P394）　<span class="quiz-src">自编</span></p></details><p><a id="q48" class="quiz-anchor"></a></p><p><strong>48.</strong> （ ）不是活动历时估算依据。</p><ul><li>A．范围基准</li><li>B．资源需求</li><li>C．风险登记册</li><li>D．项目进度计划</li></ul><details class="quiz" data-q="48" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：项目进度计划不是活动历时估算的依据，进度管理计划才是（P393）　<span class="quiz-src">自编</span></p></details><p><a id="q49" class="quiz-anchor"></a></p><p><strong>49.</strong> 某项活动最可能时间 8 天，最乐观时间 7 天，最悲观时间 12 天，则该活动的期望持续时间为（ ）。</p><ul><li>A．7 天</li><li>B．8 天</li><li>C．9 天</li><li>D．10 天</li></ul><details class="quiz" data-q="49" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：三角分布 (7+12+8)/3=9；贝塔分布 (7+12+4×8)/6=51/6（P394）　<span class="quiz-src">自编</span></p></details><p><a id="q50" class="quiz-anchor"></a></p><p><strong>50.</strong> 估算活动持续时间时需要参考的依据不包括（ ）。</p><ul><li>A．估算依据</li><li>B．进度管理计划</li><li>C．风险登记册</li><li>D．范围基准</li></ul><details class="quiz" data-q="50" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：估算依据是估算活动持续时间的输出，不是依据（P393-394）　<span class="quiz-src">自编</span></p></details><p><a id="q51" class="quiz-anchor"></a></p><p><strong>51.</strong> （ ）利用历史数据之间的统计关系和其他变量，来进行项目工作的成本估算。</p><ul><li>A．类比估算</li><li>B．参数估算</li><li>C．自下而上估算</li><li>D．三点估算</li></ul><details class="quiz" data-q="51" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：参数估算是利用历史数据之间的统计关系和其他变量进行估算（P394）　<span class="quiz-src">自编</span></p></details><p><a id="q52" class="quiz-anchor"></a></p><p><strong>52.</strong> （ ）的准确性取决于模型的成熟度和基础数据的可靠性。</p><ul><li>A．类比估算</li><li>B．三点估算</li><li>C．自下而上估算</li><li>D．参数估算</li></ul><details class="quiz" data-q="52" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：参数估算的准确性取决于参数模型的成熟度和基础数据的可靠性（P394）　<span class="quiz-src">自编</span></p></details><p><a id="q53" class="quiz-anchor"></a></p><p><strong>53.</strong> 关于估算活动持续时间的说法中不正确的是（ ）。</p><ul><li>A．估算活动持续时间的主要作用是确定完成每个活动所需花费的时间量</li><li>B．随着数据越来越详细，越来越准确，持续时间估算的准确性和质量也会越来越高</li><li>C．帕金森定律指出人们只有在最后一刻，即快到期限时才会全力以赴</li><li>D．类比估算是一种使用相似活动或项目的历史数据来估算当前活动或项目的持续时间或成本的技术</li></ul><details class="quiz" data-q="53" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：&quot;最后一刻才全力以赴&quot;是拖延症；帕金森定律指只要还有时间，工作就会不断扩展（P392）　<span class="quiz-src">自编</span></p></details><p><a id="q54" class="quiz-anchor"></a></p><p><strong>54.</strong> 三点估算中贝塔分布的计算公式为（ ）。</p><ul><li>A．CE=（Co+Cm+Cp）/3</li><li>B．CE=（Co+4Cm+Cp）/6</li><li>C．CE=（Co+Cm+Cp）/6</li><li>D．CE=（Co+4Cm+Cp）/3</li></ul><details class="quiz" data-q="54" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：贝塔分布 CE=（Co+4Cm+Cp）/6（P394）　<span class="quiz-src">自编</span></p></details><p><a id="q55" class="quiz-anchor"></a></p><p><strong>55.</strong> 项目经理在接手项目 A 时，由于处于项目初期，仅了解了 WBS 的几个高层级情况，这个时候应该采用哪种方式来估算资源更合适（ ）。</p><ul><li>A．专家判断</li><li>B．自下而上估算</li><li>C．类比估算</li><li>D．参数估算</li></ul><details class="quiz" data-q="55" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：类比估算以过去类似项目的参数值为基础，适合项目详细信息不足时使用（P393-394）　<span class="quiz-src">自编</span></p></details><p><a id="q56" class="quiz-anchor"></a></p><p><strong>56.</strong> 项目经理在对项目 A 的某一子系统进行估算时，发现该子系统一共包含 12 个功能点，这些功能点公司有现成的代码库和估算公式，于是项目经理直接根据公司提供的估算公式输入功能点数进行了估算，请问采用的是估算方法（ ）。</p><ul><li>A．专家判断</li><li>B．自下而上估算</li><li>C．类比估算</li><li>D．参数估算</li></ul><details class="quiz" data-q="56" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：参数估算基于历史数据和项目参数，使用算法或统计关系计算所需资源数量（P394）　<span class="quiz-src">自编</span></p></details><p><a id="q57" class="quiz-anchor"></a></p><p><strong>57.</strong> 某研发负责人对软件研发时间的乐观估算，最可能估算和悲观估算分别为 20 天，30 天和 50 天。假设三个估算值服从三角分布，则期望持续时间为（ ）天。</p><ul><li>A．31.7</li><li>B．30</li><li>C．33.3</li><li>D．40</li></ul><details class="quiz" data-q="57" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：三角分布 Te=（乐观+最可能+悲观）/3=（20+30+50）/3≈33.3（P394）　<span class="quiz-src">2024 年中项第 1 批</span></p></details><p><a id="q58" class="quiz-anchor"></a></p><p><strong>58.</strong> 估算活动持续时间时需要考虑的其他因素包括（ ）。</p><p>①收益递减规律；②活动清单；③绩效测量规则；④资源数量；⑤员工激励；⑥里程碑清单；⑦技术进步</p><ul><li>A．①④⑤⑦</li><li>B．②⑤④⑦</li><li>C．①③④⑥</li><li>D．②③⑤⑥</li></ul><details class="quiz" data-q="58" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：其他因素包括收益递减规律、资源数量、技术进步和员工激励等（P392）　<span class="quiz-src">2024 年中项第 3 批</span></p></details><p><a id="q59" class="quiz-anchor"></a></p><p><strong>59.</strong> 某项目正常情况需 15 天完成，最快 8 天可完成，考虑到客户可能需更多的需求核实，最多需 25 天完成，按照贝塔分布，则该项目估算工期为（ ）天。</p><ul><li>A．20</li><li>B．16</li><li>C．15.5</li><li>D．11.5</li></ul><details class="quiz" data-q="59" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：贝塔分布估算工期=（8+25+4×15）/6=15.5（P394）　<span class="quiz-src">2024 年中项第 3 批</span></p></details><p><a id="q60" class="quiz-anchor"></a></p><p><strong>60.</strong> （ ）估算方法将以往类似项目的相关信息作为估算未来项目的基础，是一种快速估算方法，适用于项目经理只能识别 WBS 的几个高层级的情况。</p><ul><li>A．类比</li><li>B．基线</li><li>C．自下而上</li><li>D．参数</li></ul><details class="quiz" data-q="60" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：类比估算以类似项目参数值为基础，是粗略、快速的估算方法（P393-394）　<span class="quiz-src">2023 年下高项第 3 批</span></p></details><p><a id="q61" class="quiz-anchor"></a></p><p><strong>61.</strong> 一位软件工程师在进行软件项目持续时间估算时，按照&quot;代码行&quot;为单位进行估算，采用的估算方法是（ ）。</p><ul><li>A．三点估算</li><li>B．类比估算</li><li>C．参数估算</li><li>D．专家判断</li></ul><details class="quiz" data-q="61" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：&quot;代码行&quot;属面向规模的度量，按既定参数模型计算开发时长属参数估算（P394）　<span class="quiz-src">2023 年下高项第 3 批</span></p></details><p><a id="q62" class="quiz-anchor"></a></p><p><strong>62.</strong> 关于估算活动持续时间的工具与技术的描述，不正确的是（ ）。</p><ul><li>A．类比估算是一种精确的估算方法，适用于项目详细信息充分、项目需求明确的情况</li><li>B．专家判断依赖于专家的可用性和经验，可能受到主观判断的影响</li><li>C．三点估算考虑了估算中的不确定性和风险，有助于界定活动持续时间的近似区间</li><li>D．参数估算是一种基于历史数据和项目参数，使用某种算法来计算成本或持续时间的估算技术</li></ul><details class="quiz" data-q="62" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：类比估算是一种粗略的估算方法，优点是成本低、耗时少，缺点是准确性低（P394）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q63" class="quiz-anchor"></a></p><p><strong>63.</strong> 某项目活动 A 的最乐观时间为 9 天，最悲观时间为 21 天，最可能时间为 12 天，客户希望提前 2 天完成该活动。项目经理使用三点估算法计算了该活动的期望持续时间，如果完成的概率符合正态分布，则该活动的期望持续时间和提前 2 天完成概率是（ ）。</p><ul><li>A．11 天、16%</li><li>B．13 天、16%</li><li>C．11 天、32%</li><li>D．13 天、32%</li></ul><details class="quiz" data-q="63" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：期望时间=（9+21+4×12）/6=13，标准差=（21-9）/6=2；提前 2 天即 11 天内完成，概率 50%-34%=16%（P394）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q64" class="quiz-anchor"></a></p><p><strong>64.</strong> β 分布，三点估算求工期，乐观 5，最可能 8，悲观 17，求预期工期（ ）。</p><ul><li>A．9 天</li><li>B．8 天</li><li>C．12 天</li><li>D．11 天</li></ul><details class="quiz" data-q="64" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：三点估算（β 分布）预期工期=（5+4×8+17）/6=9（P394）　<span class="quiz-src">2025 年中项第 2 批</span></p></details><p><a id="q65" class="quiz-anchor"></a></p><p><strong>65.</strong> 某社区图书馆改造项目需要估算成本，项目经理参考本市其他社区图书馆改造项目的实际成本 800 万元，结合本社区特点估算成本为 850 万元。项目经理采用的成本估算方法是（ ）。</p><ul><li>A．自下而上估算</li><li>B．三点估算</li><li>C．类比估算</li><li>D．参数估算</li></ul><details class="quiz" data-q="65" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：以类似项目历史数据为基础估算，并按已知差异调整，属类比估算（P393-394）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q66" class="quiz-anchor"></a></p><p><strong>66.</strong> 制订进度计划的关键步骤是（ ）。</p><p>①分析进度计划，确定是否存在逻辑关系冲突，以及在批准进度计划并将其作为基准之前是否需要资源平衡，并同步修订和维护项目进度模型；②定义项目里程碑，识别活动并排列活动顺序，估算持续时间，并确定活动的开始和完成日期；③项目人员确认开始和完成日期与资源日历和其他项目或任务没有冲突，从而确认计划日期的有效性；④由分配至各个活动的项目人员审查其被分配的活动</p><ul><li>A．①②③④</li><li>B．②④③①</li><li>C．②③④①</li><li>D．①③④②</li></ul><details class="quiz" data-q="66" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：先按②定义里程碑、排序、估算并定日期，再④审查分配，③确认无冲突，①分析逻辑冲突并做资源平衡（P396）　<span class="quiz-src">自编</span></p></details><p><a id="q67" class="quiz-anchor"></a></p><p><strong>67.</strong> 制订进度计划时需要参考的依据不包括（ ）。</p><ul><li>A．项目进度计划</li><li>B．范围基准</li><li>C．资源需求</li><li>D．资源日历</li></ul><details class="quiz" data-q="67" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目进度计划是制订进度计划的输出，不是依据（P402）　<span class="quiz-src">自编</span></p></details><p><a id="q68" class="quiz-anchor"></a></p><p><strong>68.</strong> （ ）不属于制订进度计划的输入。</p><ul><li>A．进度管理计划</li><li>B．范围基准</li><li>C．活动清单</li><li>D．进度基准</li></ul><details class="quiz" data-q="68" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：进度基准是制订进度计划的输出（P402）　<span class="quiz-src">自编</span></p></details><p><a id="q69" class="quiz-anchor"></a></p><p><strong>69.</strong> 关于进度管理的描述，不正确的是（ ）。</p><ul><li>A．项目开展过程中，关键路径可能会发生变化</li><li>B．关键路径上的活动的总浮动时间和自由浮动时间都为 0</li><li>C．资源平滑技术通常会导致项目关键路径变长</li><li>D．关键链法在关键路径法基础上，考虑了资源因素</li></ul><details class="quiz" data-q="69" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：资源平滑不改变项目关键路径，完工日期也不会延迟；导致关键路径变长的是资源平衡（P399）　<span class="quiz-src">自编</span></p></details><p><a id="q70" class="quiz-anchor"></a></p><p><strong>70.</strong> 在关键路径上增加资源不一定会缩短项目的工期，这是因为（ ）。</p><ul><li>A．关键路径上的活动是不依赖于时间和资源的</li><li>B．关键活动所配置的资源数量总是充足的</li><li>C．关键活动的历时是固定不变的</li><li>D．增加资源有可能导致产生额外的问题并且降低效率</li></ul><details class="quiz" data-q="70" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：增加资源不一定能缩减活动工期，反而可能带来额外问题并降低效率（P392-400）　<span class="quiz-src">自编</span></p></details><p><a id="q71" class="quiz-anchor"></a></p><p><strong>71.</strong> 在计划编制完成后，项目团队认为所制定的进度时间太长，分析表明不能改变工作网络图，但该项目有附加的资源可利用。项目经理采用的最佳方式是（ ）。</p><ul><li>A．快速追踪项目</li><li>B．引导一项蒙特卡洛分析</li><li>C．利用参数估算</li><li>D．赶工</li></ul><details class="quiz" data-q="71" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：网络图不能改说明无法并行，只能通过增加资源赶工压缩关键路径活动（P400）　<span class="quiz-src">自编</span></p></details><p><a id="q72" class="quiz-anchor"></a></p><p><strong>72.</strong> 下面关于制订进度计划的说法中不正确的是（ ）。</p><ul><li>A．制订可行的项目进度计划是一个反复进行的过程</li><li>B．制订进度计划的主要作用是为完成项目活动而制定具有计划日期的进度模型</li><li>C．关键路径上的活动的总时差和自由时差总是为 0</li><li>D．资源平滑是对进度模型中的活动进行调整，从而使项目资源需求不超过预定的资源限制的一种技术，其有可能导致关键路径改变，而且通常是延长了关键路径</li></ul><details class="quiz" data-q="72" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：资源平滑不会改变关键路径，完工日期也不会延迟；描述的是资源平衡（P399）　<span class="quiz-src">自编</span></p></details><p><a id="q73" class="quiz-anchor"></a></p><p><strong>73.</strong> 快速跟进是一种进度压缩技术，（ ）属于快速跟进技术。</p><ul><li>A．加班</li><li>B．增加项目组成员</li><li>C．加快关键路径上的活动</li><li>D．将正常情况下按顺序进行的活动或阶段改为至少是部分并行开展</li></ul><details class="quiz" data-q="73" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：快速跟进把顺序进行的活动或阶段改为至少部分并行开展（P400）　<span class="quiz-src">自编</span></p></details><p><a id="q74" class="quiz-anchor"></a></p><p><strong>74.</strong> 项目经理小张在查看各组研发计划时，发现有三个小组计划在同一周进行系统架构设计，而项目组只有一位资深架构师，不可能在一周内完成三组的架构设计工作。于是小张和各组长商量在不影响项目进度的前提下，将三组的系统架构设计活动稍微错开几天，确保资深架构师可以完成所有的设计工作。此处小张运用的进度管理技术是（ ）。</p><ul><li>A．资源平衡</li><li>B．资源平滑</li><li>C．赶工</li><li>D．快速跟进</li></ul><details class="quiz" data-q="74" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：&quot;不影响项目进度的前提下错开活动&quot;是资源平滑，资源平滑不影响项目工期（P399）　<span class="quiz-src">自编</span></p></details><p><a id="q75" class="quiz-anchor"></a></p><p><strong>75.</strong> 关于进度管理，不正确的是（ ）。</p><ul><li>A．在项目进行过程中，关键路径可能会不断变化</li><li>B．自由浮动时间是指在不延误任何紧后活动的最早开始时间且不违反进度制约因素的前提下，活动可以从最早开始时间推迟或拖延的时间量</li><li>C．关键链法建立在关键路径法之上，考虑了资源分配、资源优化、资源平衡和活动历时不确定性对关键路径的影响</li><li>D．资源平滑技术可能导致关键路径改变，通常是延长</li></ul><details class="quiz" data-q="75" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：资源平滑不改变关键路径，活动只在其自由和总浮动时间内延迟（P399）　<span class="quiz-src">自编</span></p></details><p><a id="q76" class="quiz-anchor"></a></p><p><strong>76.</strong> 在制定进度计划时，可以采用多种工具与技术，如关键路径法、资源平衡技术、资源平滑技术等，在以下叙述中，不正确的是（ ）。</p><ul><li>A．项目的关键路径可能有一条或多条</li><li>B．随着项目的开展，关键路径可能也随着不断变化</li><li>C．资源平衡技术往往会导致关键路径延长</li><li>D．资源平滑技术往往会改变项目关键路径，导致项目进度延迟</li></ul><details class="quiz" data-q="76" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：资源平滑不改变关键路径，也不会导致完工日期延迟（P399）　<span class="quiz-src">自编</span></p></details><p><a id="q77" class="quiz-anchor"></a></p><p><strong>77.</strong> 通过增加资源来压缩进度工期的技术称为（ ）。</p><ul><li>A．快速跟进</li><li>B．持续时间缓冲</li><li>C．赶工</li><li>D．提前量管理</li></ul><details class="quiz" data-q="77" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：赶工是通过增加资源、以最小的成本代价压缩进度工期的技术（P400）　<span class="quiz-src">自编</span></p></details><p><a id="q78" class="quiz-anchor"></a></p><p><strong>78.</strong> 关于制定进度计划的工具和技术的描述，不正确的是（ ）。</p><ul><li>A．总浮动的时间等于本活动的最迟完成时间减去本活动的最早完成时间</li><li>B．自由浮动时间等于紧后活动的最早开始时间的最小值减去本活动的最早完成时间</li><li>C．资源平滑技术通过缩短项目的关键路径来缩短完工时间</li><li>D．关键路径上活动的总浮动时间与自由浮动时间都为 0</li></ul><details class="quiz" data-q="78" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：资源平滑不改变关键路径，也不缩短完工时间（P399）　<span class="quiz-src">自编</span></p></details><p><a id="q79" class="quiz-anchor"></a></p><p><strong>79.</strong> 以下关于制订进度计划的说法不正确的是（ ）。</p><ul><li>A．敏捷或适应型发布规划基于项目路线图和产品发展愿景，提供了高度概括的发布进度时间轴（通常是 3～6 个月）</li><li>B．进度基准是经过批准的进度模型，只有通过正式的变更控制程序才能进行变更，用作与实际结果进行比较的依据</li><li>C．进度基准应包含基准开始日期和基准结束日期</li><li>D．概括性进度计划，也叫里程碑图</li></ul><details class="quiz" data-q="79" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：里程碑进度计划即里程碑图；概括性进度计划即横道图；详细进度计划即项目进度网络图（P402）　<span class="quiz-src">自编</span></p></details><p><a id="q80" class="quiz-anchor"></a></p><p><strong>80.</strong> 某项目活动关系和工期如下表所示，假设活动 F 的工期延长 2 天，则项目总工期延长（ ）天。</p><table><thead><tr><th>活动</th><th>紧前活动</th><th>工期（天）</th></tr></thead><tbody><tr><td>A</td><td>-</td><td>3</td></tr><tr><td>B</td><td>A</td><td>2</td></tr><tr><td>C</td><td>A</td><td>1</td></tr><tr><td>D</td><td>A</td><td>6</td></tr><tr><td>E</td><td>B、C</td><td>4</td></tr><tr><td>F</td><td>E</td><td>2</td></tr><tr><td>G</td><td>D</td><td>3</td></tr><tr><td>H</td><td>F、G</td><td>2</td></tr></tbody></table><ul><li>A．2</li><li>B．1</li><li>C．3</li><li>D．0</li></ul><details class="quiz" data-q="80" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：关键路径为 ADGH，工期 14 天；经 F 的最长路径 ABEFH=13 天，F 总时差 1 天，F 延误 2 天工期延长 1 天（P396-402）　<span class="quiz-src">2024 年中项第 2 批</span></p></details><p><a id="q81" class="quiz-anchor"></a></p><p><strong>81.</strong> 当前某项目处于进度滞后，成本节约的状态，为了保证项目按时保质完成，后续应优先采取的措施是（ ）。</p><ul><li>A．赶工，投入更多的资源或增加工作时间</li><li>B．降低质控要求，减少问题，减少返工</li><li>C．减小活动范围或降低活动要求</li><li>D．快速跟进，并行施工，缩短关键路径长度</li></ul><details class="quiz" data-q="81" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：成本有节约，可通过增加资源赶工加快关键路径活动；降质、缩范围均不可取；并行在成本节约时不如赶工（P400）　<span class="quiz-src">2024 年中项第 3 批</span></p></details><p><a id="q82" class="quiz-anchor"></a></p><p><strong>82.</strong> 某项目的网络图如下（原题附图，各活动标注最早开始、工期与最早完成时间），活动 C 的自由浮动时间为（ ）天。</p><ul><li>A．0</li><li>B．1</li><li>C．2</li><li>D．3</li></ul><details class="quiz" data-q="82" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：自由时差 = MIN（紧后活动最早开始时间）- 本活动最早完成时间；活动 F 最早开始 7 天，C 只有 F 一个紧后活动，7-6=1（P397-398）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q83" class="quiz-anchor"></a></p><p><strong>83.</strong> 在（ ）规定可以开展进度活动的可用工作日和工作班次，它把可用于开展进度活动的时间段（按天或更小的时间单位）与不可用的时间段区分开来。</p><ul><li>A．项目日历</li><li>B．资源日历</li><li>C．项目团队派工单</li><li>D．物质资源分配单</li></ul><details class="quiz" data-q="83" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：项目日历规定可开展进度活动的可用工作日和工作班次（P404）　<span class="quiz-src">2023 年下高项第 2 批</span></p></details><p><a id="q84" class="quiz-anchor"></a></p><p><strong>84.</strong> 某项目包含 A、B、C、D、E、F、G、H、I、J 共 10 个活动，各活动历时与逻辑关系如下表所示，施工过程中，活动 B 延期 2 天，项目工期是（ ）天。</p><table><thead><tr><th>活动名称</th><th>活动历时（天）</th><th>前置活动</th></tr></thead><tbody><tr><td>A</td><td>2</td><td>-</td></tr><tr><td>B</td><td>2</td><td>A</td></tr><tr><td>C</td><td>3</td><td>A</td></tr><tr><td>D</td><td>4</td><td>A</td></tr><tr><td>E</td><td>3</td><td>B</td></tr><tr><td>F</td><td>4</td><td>C、D</td></tr><tr><td>G</td><td>4</td><td>E、F</td></tr><tr><td>H</td><td>3</td><td>G</td></tr><tr><td>I</td><td>2</td><td>G</td></tr><tr><td>J</td><td>1</td><td>H、I</td></tr></tbody></table><ul><li>A．17</li><li>B．18</li><li>C．19</li><li>D．20</li></ul><details class="quiz" data-q="84" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：关键路径 ADFGHJ=18 天；B 的总时差为 3 天，延期 2 天对工期没有影响（P397-398）　<span class="quiz-src">2023 年下高项第 2 批</span></p></details><p><a id="q85" class="quiz-anchor"></a></p><p><strong>85.</strong> （ ）不属于项目进度计划的图形表示方式。</p><ul><li>A．横道图</li><li>B．矩阵图</li><li>C．项目进度网络图</li><li>D．里程碑图</li></ul><details class="quiz" data-q="85" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：常用进度计划图形为横道图、里程碑图和项目进度网络图（P402）　<span class="quiz-src">2023 年下高项第 3 批</span></p></details><p><a id="q86" class="quiz-anchor"></a></p><p><strong>86.</strong> 某项目经理负责一个软件开发项目，活动和它们之间的依赖关系：活动 A：需求分析，预计耗时 2 天。活动 B：设计，依赖于活动 A 的完成，预计耗时 3 天。活动 C：编码，依赖于活动 B 的完成，预计耗时 5 天。活动 D：测试，与活动 C 同时开展，但必须在活动 C 完成后才能完全结束，预计耗时 7 天。活动 E：部署，依赖于活动 C 和 D 的完成，预计耗时 2 天。根据上述活动和它们的依赖关系，项目工期为（ ）天。</p><ul><li>A．14</li><li>B．12</li><li>C．13</li><li>D．19</li></ul><details class="quiz" data-q="86" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：2+3+7+2=14；D 与 C 为开始-开始并带完成-完成约束（P397-398）　<span class="quiz-src">2024 年高项第 1 批</span></p></details><p><a id="q87" class="quiz-anchor"></a></p><p><strong>87.</strong> 某项目的活动持续时间及逻辑关系如下表所示，该项目总工期是（ ）天。</p><table><thead><tr><th>活动</th><th>持续时间（天）</th><th>紧前活动</th></tr></thead><tbody><tr><td>A</td><td>2</td><td>无</td></tr><tr><td>B</td><td>3</td><td>A</td></tr><tr><td>C</td><td>4</td><td>A</td></tr><tr><td>D</td><td>2</td><td>B</td></tr><tr><td>E</td><td>5</td><td>B</td></tr><tr><td>F</td><td>3</td><td>C</td></tr><tr><td>G</td><td>1</td><td>D、E</td></tr><tr><td>H</td><td>4</td><td>F、G</td></tr></tbody></table><ul><li>A．16</li><li>B．14</li><li>C．13</li><li>D．15</li></ul><details class="quiz" data-q="87" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：关键路径 ABEGH，工期 2+3+5+1+4=15 天（P397-398）　<span class="quiz-src">2025 年高项第 1 批</span></p></details><p><a id="q88" class="quiz-anchor"></a></p><p><strong>88.</strong> 某项目活动工期的乐观时间为 8 天，最可能时间为 14 天，悲观时间为 26 天，如果三个估算值服从三角分布，那么该活动的期望持续时间为（ ）天。</p><ul><li>A．15</li><li>B．16</li><li>C．18</li><li>D．12</li></ul><details class="quiz" data-q="88" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：三角分布 Te=（乐观+最可能+悲观）/3=（8+14+26）/3=16（P394）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q89" class="quiz-anchor"></a></p><p><strong>89.</strong> 某项目在进度规划时用到计划评审技术（PERT），估算整个项目完成时间的数学期望为 53 周，方差为 49。那么项目在（ ）周到（ ）周之间完成的概率为 95%。</p><ul><li>A．45、61</li><li>B．39、67</li><li>C．46、60</li><li>D．32、74</li></ul><details class="quiz" data-q="89" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：方差 49，标准差 7；95% 概率为正态分布期望值前后两个标准差，53±14（P394）　<span class="quiz-src">2026 年上半年中项第 1 批</span></p></details><p><a id="q90" class="quiz-anchor"></a></p><p><strong>90.</strong> 某项目有 A～J 共十个活动，各活动历时估算与逻辑关系如下表所示，求项目工期（ ）。</p><table><thead><tr><th>活动</th><th>紧前</th><th>工期</th></tr></thead><tbody><tr><td>A</td><td>-</td><td>2</td></tr><tr><td>B</td><td>-</td><td>3</td></tr><tr><td>C</td><td>A</td><td>4</td></tr><tr><td>D</td><td>A</td><td>3</td></tr><tr><td>E</td><td>B、D</td><td>5</td></tr><tr><td>F</td><td>D</td><td>4</td></tr><tr><td>G</td><td>C、F</td><td>2</td></tr><tr><td>H</td><td>G</td><td>3</td></tr><tr><td>I</td><td>G、E</td><td>6</td></tr><tr><td>J</td><td>H、I</td><td>3</td></tr></tbody></table><ul><li>A．19</li><li>B．20</li><li>C．22</li><li>D．17</li></ul><details class="quiz" data-q="90" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：关键路径为 ADFGIJ，总工期 2+3+4+2+6+3=20 天（P397-398）　<span class="quiz-src">2026 年上半年中项第 2 批</span></p></details><p><a id="q91" class="quiz-anchor"></a></p><p><strong>91.</strong> （ ）的主要作用是在整个项目期间保持对进度基准的维护。</p><ul><li>A．规划进度管理</li><li>B．排列活动顺序</li><li>C．制定进度计划</li><li>D．控制进度</li></ul><details class="quiz" data-q="91" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：控制进度是监督项目状态，以更新项目进度和管理进度基准变更的过程（P506）　<span class="quiz-src">自编</span></p></details><p><a id="q92" class="quiz-anchor"></a></p><p><strong>92.</strong> （ ）属于控制进度的工作内容。</p><ul><li>A．确定完成项目工作所需花费的时间量</li><li>B．确定完成项目工作所需的资源</li><li>C．确定工作之间的逻辑关系</li><li>D．在变更实际发生时对其进行管理</li></ul><details class="quiz" data-q="92" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：控制进度关注判断当前状态、影响引起变更的因素、重估进度储备、判断是否已变更、变更发生时加以管理（P507）　<span class="quiz-src">自编</span></p></details><p><a id="q93" class="quiz-anchor"></a></p><p><strong>93.</strong> 进度控制是避免工期拖延的一种方法。进度控制中的纠正行为通常加速某些活动以确保这些活动能够及时完成。为了重新编制和执行进度表，纠正行为通常要求（ ）。</p><ul><li>A．做大家都不喜欢的决策</li><li>B．及时调整基线</li><li>C．进行原因分析</li><li>D．资源平衡</li></ul><details class="quiz" data-q="93" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：纠正偏差首先要进行原因分析，其次才决定是否调整基准（P507）　<span class="quiz-src">自编</span></p></details><p><a id="q94" class="quiz-anchor"></a></p><p><strong>94.</strong> （ ）检查项目绩效随时间的变化情况，可用于确定绩效是在改善还是在恶化。</p><ul><li>A．备选方案分析</li><li>B．成本效益分析</li><li>C．绩效审查</li><li>D．趋势分析</li></ul><details class="quiz" data-q="94" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：趋势分析检查项目绩效随时间的变化情况，确定绩效是在改善还是在恶化（P509）　<span class="quiz-src">自编</span></p></details><p><a id="q95" class="quiz-anchor"></a></p><p><strong>95.</strong> （ ）用于追踪迭代未完项中尚待完成的工作。它分析与理想燃尽图的偏差。可使用预测趋势线来预测迭代结束时可能出现的偏差。</p><ul><li>A．趋势分析</li><li>B．迭代燃尽图</li><li>C．挣值分析</li><li>D．偏差分析</li></ul><details class="quiz" data-q="95" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：迭代燃尽图用对角线表示理想燃尽情况，再逐日绘制实际剩余工作并计算趋势线（P508-509）　<span class="quiz-src">自编</span></p></details><p><a id="q96" class="quiz-anchor"></a></p><p><strong>96.</strong> 控制项目进度时常用的技术不包括（ ）。</p><ul><li>A．趋势分析</li><li>B．偏差分析</li><li>C．统计抽样</li><li>D．关键路径法</li></ul><details class="quiz" data-q="96" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：控制进度工具为数据分析（挣值、迭代燃尽图、绩效审查、趋势、偏差、假设情景分析）、关键路径法、资源优化、提前量和滞后量、进度压缩（P508-509）　<span class="quiz-src">自编</span></p></details><p><a id="q97" class="quiz-anchor"></a></p><p><strong>97.</strong> 如果一个项目的 SPI=0.75，CPI=0.9，此时项目经理最适合采取（ ）方式来控制项目进度。</p><ul><li>A．快速跟进</li><li>B．赶工</li><li>C．资源平衡</li><li>D．蒙特卡洛分析</li></ul><details class="quiz" data-q="97" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：SPI、CPI 均小于 1，说明进度滞后且成本超支，宜并行施工快速跟进，且不额外增加新成本（P400）　<span class="quiz-src">自编</span></p></details><p><a id="q98" class="quiz-anchor"></a></p><p><strong>98.</strong> 如果一个项目的 SPI=0.85，CPI=0.9，下面的哪种方法不适用（ ）。</p><ul><li>A．快速跟进</li><li>B．赶工</li><li>C．经过客户同意，减小活动范围或降低活动要求</li><li>D．改进方法或技术，以提高生产效率</li></ul><details class="quiz" data-q="98" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：SPI、CPI 均小于 1 即进度滞后且成本超支；A、C、D 可用，赶工会进一步增加成本（P400）　<span class="quiz-src">自编</span></p></details><p><a id="q99" class="quiz-anchor"></a></p><p><strong>99.</strong> 项目进度控制是依据项目进度基准计划对项目的实际进度进行监控，使项目能够按时完成，以下关于项目进度控制的叙述中（ ）是不正确的。</p><ul><li>A．项目进度至关重要，因此进度控制需要在项目初期优先关注</li><li>B．进度控制必须与其他变化控制，包括成本控制与范围控制紧密结合</li><li>C．项目进度控制是项目整体控制的一个组成部分</li><li>D．对项目进度的控制，应重点关注项目进展报告和执行状态报告</li></ul><details class="quiz" data-q="99" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：进度控制要贯穿于项目始终，且需在整个项目期间开展，不是只在项目初期优先关注（P506-507）　<span class="quiz-src">自编</span></p></details><p><a id="q100" class="quiz-anchor"></a></p><p><strong>100.</strong> 控制进度时需要参考的依据不包括（ ）。</p><ul><li>A．假设日志</li><li>B．进度基准</li><li>C．范围基准</li><li>D．绩效测量基准</li></ul><details class="quiz" data-q="100" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：依据为项目管理计划（进度管理计划、进度基准、范围基准、绩效测量基准）、项目文件（资源日历、项目进度计划、项目日历、进度数据、经验教训登记册）、工作绩效数据（P508）　<span class="quiz-src">自编</span></p></details><p><a id="q101" class="quiz-anchor"></a></p><p><strong>101.</strong> 关于进度控制的说法中不正确的是（ ）。</p><ul><li>A．进度控制的主要作用是在整个项目期间保持对进度基准的维护</li><li>B．进度控制在项目中期需要尤其关注</li><li>C．将工作外包时，需定期考察供应商的进度是否正常</li><li>D．控制进度流程应作为实施整体变更控制过程的一部分</li></ul><details class="quiz" data-q="101" data-answer="B"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：B</strong>｜考点：进度控制在整个项目期间开展并随实际情况调整，不存在&quot;中期尤其关注&quot;的说法（P506-507）　<span class="quiz-src">自编</span></p></details><p><a id="q102" class="quiz-anchor"></a></p><p><strong>102.</strong> 在控制进度过程的数据分析技术中，（ ）可以通过检查项目绩效随时间的变化情况，确定绩效是在改善还是恶化。</p><ul><li>A．储备分析</li><li>B．蒙特卡洛分析</li><li>C．趋势分析</li><li>D．假设情景分析</li></ul><details class="quiz" data-q="102" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：趋势分析检查项目绩效随时间的变化情况，以确定绩效是在改善还是在恶化（P509）　<span class="quiz-src">2023 年上半年高项</span></p></details><p><a id="q103" class="quiz-anchor"></a></p><p><strong>103.</strong> 项目进度管理过程中，可用于控制进度过程的数据分析技术包括（ ）。</p><ul><li>A．蒙特卡洛分析</li><li>B．计划评审技术（PERT）</li><li>C．参数估算</li><li>D．挣值分析</li></ul><details class="quiz" data-q="103" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：控制进度的数据分析技术包括挣值分析、迭代燃尽图、绩效审查、趋势分析、偏差分析、假设情景分析；蒙特卡洛属风险定量分析，PERT 与参数估算属估算技术（P508-509）　<span class="quiz-src">2023 年下高项第 3 批</span></p></details><p><a id="q104" class="quiz-anchor"></a></p><p><strong>104.</strong> 在一个复杂的信息系统项目中，由于资源限制，项目经理发现关键资源（如资深开发人员）经常在不同的项目任务之间被重新分配，这导致项目进度频繁延误和质量波动，为了有效控制资源并减少对进度延误和成本超支的影响，项目经理优先采取的措施是（ ）。</p><ul><li>A．增加资源储备以应对未来的资源需求波动</li><li>B．严格限制资源在项目间的共享，确保资源专注于当前任务</li><li>C．实施资源平衡策略，优化不同任务间的资源分配</li><li>D．缩减项目范围以匹配可用资源的能力</li></ul><details class="quiz" data-q="104" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：资源受限且需控制延误与超支，宜用资源平衡策略优化分配；A 不合适、B 过严、D 缩范围不可取（P399）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q105" class="quiz-anchor"></a></p><p><strong>105.</strong> 可用于控制进度过程的数据分析技术不包括（ ）。</p><ul><li>A．备选方案分析</li><li>B．偏差分析</li><li>C．迭代燃尽图</li><li>D．趋势分析</li></ul><details class="quiz" data-q="105" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：控制进度的数据分析包括挣值分析、迭代燃尽图、绩效审查、趋势分析、偏差分析、假设情景分析；备选方案分析一般属规划过程工具（P508-509）　<span class="quiz-src">2024 年高项第 2 批</span></p></details><p><a id="q106" class="quiz-anchor"></a></p><p><strong>106.</strong> 某项目在执行阶段，项目经理通过进度绩效测量发现关键路径上的活动延迟了两周。项目经理使用关键路径法重新评估剩余工作，并决定采用快速跟进压缩后续活动工期，同时提交了变更请求以调整进度基准。上述控制进度过程的直接输出不包括（ ）。</p><ul><li>A．变更请求</li><li>B．进度预测</li><li>C．工作绩效信息</li><li>D．进度基准更新</li></ul><details class="quiz" data-q="106" data-answer="D"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：D</strong>｜考点：绩效测量得工作绩效信息、关键路径法重评属进度预测、提交变更属变更请求；进度基准更新须经批准后才可能发生（P510）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q107" class="quiz-anchor"></a></p><p><strong>107.</strong> 某企业级信息系统集成项目进入实施阶段后，项目经理发现关键路径上的活动 B 因供应商延期导致实际进度滞后 3 周。此时，客户要求项目必须按原计划交付，且公司高层明确表示无法追加预算。项目经理应优先采取以下哪项措施（ ）。</p><ul><li>A．启动快速跟进策略，将活动 B 与后续活动并行执行</li><li>B．重新评估活动 B 的依赖关系，尝试将其从关键路径中移除</li><li>C．调整非关键路径上的活动资源，优化整体进度计划</li><li>D．对活动 B 实施赶工，增加资源投入以追回延误时间</li></ul><details class="quiz" data-q="107" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：高层明确无法追加预算，不能赶工，只能采用快速跟进并行压缩工期（P400）　<span class="quiz-src">2025 年高项第 2 批</span></p></details><p><a id="q108" class="quiz-anchor"></a></p><p><strong>108.</strong> 当前项目的成本已超支，想要完工时不超过预算，不能选择的方案是（ ）。</p><ul><li>A．加强沟通</li><li>B．识别关键路径</li><li>C．赶工</li><li>D．资源平滑</li></ul><details class="quiz" data-q="108" data-answer="C"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：C</strong>｜考点：赶工需增加资源投入，会导致风险和/或成本增加，成本已超支时不可取（P400）　<span class="quiz-src">2025 年中项第 1 批</span></p></details><p><a id="q109" class="quiz-anchor"></a></p><p><strong>109.</strong> 非关键活动自由时差为 5 天，但延误了 7 天，项目经理应首先（ ）。</p><ul><li>A．分析是否影响关键路径</li><li>B．直接赶工</li><li>C．快速跟进</li><li>D．因为不是关键路径，不予理睬</li></ul><details class="quiz" data-q="109" data-answer="A"><summary><span class="quiz-sum-open">展开答案与考点</span><span class="quiz-sum-close">收起答案与考点</span></summary><p><strong>答案：A</strong>｜考点：延误 7 天超过自由时差 5 天，可能影响紧后活动并改变关键路径与总工期，应首先分析其对整体进度的影响（P397-398）　<span class="quiz-src">2025 年中项第 2 批</span></p></details></div>`,1)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};